// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
// The target can be a remote name (e.g., "origin") or a URL for direct push.
// When pushing to a URL, the "has unpushed" optimization is skipped since there are
// no remote tracking refs — git itself handles the no-op case.
// Does not check any settings — callers are responsible for gating.
func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil
	}
	defer repo.Close()

	// Check if branch exists locally
	branchRef := plumbing.NewBranchReferenceName(branchName)
	localRef, err := repo.Reference(branchRef, true)
	if err != nil {
		// No branch, nothing to push
		return nil
	}

	// Only check remote tracking refs when target is a remote name (not a URL).
	// URLs don't have tracking refs, so we always attempt the push and let git handle it.
	if !remote.IsURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
		return nil
	}

	return doPushBranch(ctx, target, branchName)
}

// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
func hasUnpushedSessionsCommon(repo *git.Repository, remoteName string, localHash plumbing.Hash, branchName string) bool {
	// Check for remote tracking ref: refs/remotes/<remoteName>/<branch>
	remoteRefName := plumbing.NewRemoteReferenceName(remoteName, branchName)
	remoteRef, err := repo.Reference(remoteRefName, true)
	if err != nil {
		// Remote branch doesn't exist yet - we have content to push
		return true
	}

	// If local and remote point to same commit, nothing to sync
	// This is the only case where we skip - any difference needs handling
	return localHash != remoteRef.Hash()
}

func displayPushTarget(target string) string {
	if remote.IsURL(target) {
		return "checkpoint remote"
	}
	return target
}

// checkpointPushBudget is one shared deadline across the initial push,
// fetch+rebase, and retry — per-attempt timeouts can stack to ~3x. var so tests
// can shrink it.
var checkpointPushBudget = 2 * time.Minute

// doPushBranch pushes the given branch to the target with fetch+merge recovery.
// The target can be a remote name or a URL.
func doPushBranch(ctx context.Context, target, branchName string) error {
	ctx, cancel := context.WithTimeout(ctx, checkpointPushBudget)
	defer cancel()

	displayTarget := displayPushTarget(target)

	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
	stop := startProgressDots(os.Stderr)

	// Try pushing first
	result, err := tryPushSessionsCommon(ctx, target, branchName)
	if err == nil {
		finishPush(ctx, stop, result, target)
		return nil
	}
	stop("")

	// Protected refs cannot be fixed by syncing and retrying.
	var protectedErr *protectedRefError
	if errors.As(err, &protectedErr) {
		printProtectedRefBlock(os.Stderr, branchName, target)
		return nil
	}

	// Push failed - likely non-fast-forward. Try to fetch and rebase.
	// Spanned (with the network fetch as a child) so the trace distinguishes
	// "the raw push is slow" from "we keep hitting contention and re-syncing".
	fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
	stop = startProgressDots(os.Stderr)

	frCtx, fetchRebaseSpan := perf.Start(ctx, "fetch_and_rebase")
	syncErr := fetchAndRebaseSessionsCommon(frCtx, target, branchName)
	fetchRebaseSpan.RecordError(syncErr)
	fetchRebaseSpan.End()
	if syncErr != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, syncErr)
		printCheckpointRemoteHint(target)
		return nil // Don't fail the main push
	}
	stop(" done")

	// Try pushing again after rebase
	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
	stop = startProgressDots(os.Stderr)

	if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
		printCheckpointRemoteHint(target)
	} else {
		finishPush(ctx, stop, result, target)
	}

	return nil
}

// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
// Only prints when the target is a URL (not the user's default remote).
func printCheckpointRemoteHint(target string) {
	if !remote.IsURL(target) {
		return
	}
	fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
	fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
}

// settingsHintOnce ensures the settings commit hint prints at most once per process.
var settingsHintOnce sync.Once

// printSettingsCommitHint prints a hint after a successful checkpoint remote push
// when the committed .entire/settings.json does not contain a checkpoint_remote config.
// entire.io discovers the external checkpoint repo by reading the committed project
// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
// (not just in settings.local.json or uncommitted local changes).
// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
// single pre-push invocation.
func printSettingsCommitHint(ctx context.Context, target string) {
	if !remote.IsURL(target) {
		return
	}
	settingsHintOnce.Do(func() {
		if isCheckpointRemoteCommitted(ctx) {
			return
		}
		fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")

	// If there are newer commits without checkpoints, ask for confirmation.
	// Merge commits (e.g., from merging main) don't count as "work" and are skipped silently.
	if result.newerCommitsExist && !force {
		fmt.Fprintf(w, "Found checkpoint in an older commit.\n")
		fmt.Fprintf(w, "There are %d newer commit(s) on this branch without checkpoints.\n", result.newerCommitCount)
		fmt.Fprintf(w, "Checkpoint from: %s %s\n\n", result.commitHash[:7], firstLine(result.commitMessage))

		shouldResume, err := promptResumeFromOlderCheckpoint()
		if err != nil {
			return err
		}
		if !shouldResume {
			fmt.Fprintf(w, "Resume cancelled.\n")
			return nil
		}
	}

	checkpointID := result.checkpointIDs[0]
	var metadata *strategy.CheckpointInfo

	store := checkpoint.NewCommittedReadStore(ctx, repo)
	store.SetBlobFetcher(FetchBlobsByHash)

	if store.CommittedReadRef() == plumbing.NewBranchReferenceName(paths.MetadataBranchName) {
		promoteRemoteTrackingMetadataBranch(ctx, repo)
	}

	// Multiple checkpoints (squash merge): resolve latest by CreatedAt timestamp.
	if len(result.checkpointIDs) > 1 {
		latestMetadata, err := resolveLatestCheckpoint(ctx, store, result.checkpointIDs)
		if err != nil {
			// No metadata available — nothing to resume from
			logging.Warn(logCtx, "resolveLatestCheckpoint failed",
				slog.Int("checkpoint_count", len(result.checkpointIDs)),
				slog.String("error", err.Error()),
			)
			fmt.Fprintf(w, "Found %d checkpoints for commit %s but metadata is not available\n",
				len(result.checkpointIDs), result.commitHash[:7])
			return checkRemoteMetadata(ctx, w, errW, result.checkpointIDs[0], store.CommittedReadRef())
		}
		skipped := len(result.checkpointIDs) - 1
		fmt.Fprintf(w, "Found %d checkpoints for commit %s, resuming from the latest (%d older checkpoints skipped)\n",
			len(result.checkpointIDs), result.commitHash[:7], skipped)
		checkpointID = latestMetadata.CheckpointID
		metadata = latestMetadata
	}

	if metadata == nil {
		storeInfo, storeErr := readCheckpointInfoFromStore(ctx, store, checkpointID)
		if storeErr == nil {
			metadata = storeInfo
		} else {
			logging.Debug(ctx, "checkpoint store metadata read failed",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.String("error", storeErr.Error()),
			)
			logging.Warn(logCtx, "checkpoint metadata read failed, checking remote",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.String("error", storeErr.Error()),
			)
			return checkRemoteMetadata(ctx, w, errW, checkpointID, store.CommittedReadRef())
		}
	}

	logging.Debug(logCtx, "checkpoint metadata read successfully",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("session_id", metadata.SessionID),
		slog.Int("session_count", metadata.SessionCount),
	)

	return resumeSession(ctx, w, errW, metadata, force)
}

// resolveLatestCheckpoint reads metadata for each checkpoint ID and returns
// the checkpoint with the latest CreatedAt.
func resolveLatestCheckpoint(ctx context.Context, store *checkpoint.GitStore, checkpointIDs []id.CheckpointID) (*strategy.CheckpointInfo, error) {
	infoMap := make(map[id.CheckpointID]strategy.CheckpointInfo, len(checkpointIDs))
	for _, cpID := range checkpointIDs {
		metadata, readErr := readCheckpointInfoFromStore(ctx, store, cpID)
		if readErr != nil {
			logging.Debug(ctx, "resolveLatestCheckpoint: checkpoint metadata read failed",
				slog.String("checkpoint_id", cpID.String()),
				slog.String("error", readErr.Error()),
			)
			continue
		}
		infoMap[cpID] = *metadata
	}
	latest, found := strategy.ResolveLatestCheckpointFromMap(checkpointIDs, infoMap)
	if !found {
		return nil, errors.New("no checkpoint metadata found")
	}
	return &latest, nil
}

func readCheckpointInfoFromStore(ctx context.Context, store checkpoint.CommittedListReader, checkpointID id.CheckpointID) (*strategy.CheckpointInfo, error) {
	summary, err := checkpoint.ReadCommittedCheckpoint(ctx, store, checkpointID)
	if err != nil {
		return nil, fmt.Errorf("read checkpoint: %w", err)
	}
	info := &strategy.CheckpointInfo{
		CheckpointID:     checkpointID,
		CheckpointsCount: summary.CheckpointsCount,
		FilesTouched:     summary.FilesTouched,
		SessionCount:     len(summary.Sessions),
	}
	for i := range summary.Sessions {
		metadata, metaErr := store.ReadSessionMetadata(ctx, checkpointID, i)
		if metaErr != nil {
			logging.Debug(ctx, "read checkpoint metadata: session metadata read failed",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.Int("session_index", i),
				slog.String("error", metaErr.Error()),
			)
			continue
		}
		info.SessionIDs = append(info.SessionIDs, metadata.SessionID)
		if metadata.SessionID != "" {
			info.SessionID = metadata.SessionID
			info.CreatedAt = metadata.CreatedAt
			info.Agent = metadata.Agent
			info.IsTask = metadata.IsTask
			info.ToolUseID = metadata.ToolUseID
		}
	}
	if info.SessionID == "" {
		return nil, checkpoint.ErrCheckpointNotFound
	}
	return info, nil
}

func readCheckpointInfoFromRef(
	ctx context.Context,
	repo *git.Repository,
	committedReadRef plumbing.ReferenceName,
	checkpointID id.CheckpointID,
) (*strategy.CheckpointInfo, error) {
	store := checkpoint.NewGitStoreWithRef(repo, committedReadRef)
	store.SetBlobFetcher(FetchBlobsByHash)
	return readCheckpointInfoFromStore(ctx, store, checkpointID)
}

// getMetadataTree returns the metadata branch tree and a fresh repo handle.
// After a fetch, go-git's storer cache may be stale (new packfiles on disk
// are invisible to the repo opened before the fetch). To avoid this, each
// attempt opens a fresh repo after the fetch succeeds.
//
// Fallback order: treeless fetch → local → checkpoint_remote → full origin fetch → remote tree.
func getMetadataTree(ctx context.Context) (*object.Tree, *git.Repository, error) {
	logCtx := logging.WithComponent(ctx, "resume.getMetadataTree")

	// Helper to log ref hash for a repo's metadata branch
	logRefHash := func(repo *git.Repository, source string) {
		ref, refErr := repo.Reference(plumbing.NewBranchReferenceName("entire/checkpoints/v1"), true)
		if refErr != nil {
			logging.Debug(logCtx, "metadata branch ref not found",
				slog.String("source", source),
				slog.String("error", refErr.Error()),
			)
			return
		}
		logging.Debug(logCtx, "metadata branch ref resolved",
			slog.String("source", source),
			slog.String("ref_hash", ref.Hash().String()),
		)
	}

	// When checkpoint_remote is configured, try it first — that's where
	// checkpoint data lives. Avoids a wasted fetch from origin (which may
	// not have the metadata branch at all).
	if fetchErr := FetchMetadataFromCheckpointRemote(ctx); fetchErr == nil {
		freshRepo, freshErr := openRepository(ctx)
		if freshErr == nil {
			logRefHash(freshRepo, "checkpoint-remote")
			metadataTree, treeErr := strategy.GetMetadataBranchTree(freshRepo)
			if treeErr == nil {
				logging.Debug(logCtx, "metadata tree obtained via checkpoint remote fetch",
					slog.String("tree_hash", metadataTree.Hash.String()),
				)
				return metadataTree, freshRepo, nil
			}
			logging.Debug(logCtx, "checkpoint remote fetch succeeded but tree read failed",
				slog.String("error", treeErr.Error()),
			)
			_ = freshRepo.Close()
		}
	} else {
		logging.Debug(logCtx, "checkpoint remote fetch skipped or failed",
			slog.String("error", fetchErr.Error()),
		)
	}

	// Tip-only fetch (--depth=1) is cheap and always runs so the local lookup
	// below doesn't return stale data.
	if fetchErr := FetchMetadataTreeOnly(ctx); fetchErr == nil {
