```go
// pushRefIfNeeded pushes a ref to the given target if it has unpushed changes.
// The target can be a remote name (e.g., "origin") or a URL for direct push.
// Branch refs use the "has unpushed" optimization; non-branch refs skip it and
// let git handle the no-op case.
func pushRefIfNeeded(ctx context.Context, target string, ref plumbing.ReferenceName) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil
	}
	defer repo.Close()

	localRef, err := repo.Reference(ref, true)
	if err != nil {
		return nil
	}

	if ref.IsBranch() && !remote.IsURL(target) {
		if !hasUnpushedRef(repo, target, ref, localRef.Hash()) {
			return nil
		}
	}

	return doPushRef(ctx, target, ref)
}

// hasUnpushedRef checks whether the local ref differs from the remote-tracking
// ref for a branch.
func hasUnpushedRef(repo *git.Repository, remoteName string, ref plumbing.ReferenceName, localHash plumbing.Hash) bool {
	remoteRefName := plumbing.NewRemoteReferenceName(remoteName, ref.Short())
	remoteRef, err := repo.Reference(remoteRefName, true)
	if err != nil {
		return true
	}
	return localHash != remoteRef.Hash()
}
```

