26	// disconnectedOnce ensures the disconnection warning runs at most once per process.
27	var disconnectedOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
28	
29	// IsMetadataDisconnected checks whether the local metadata branch
30	// and the provided fetched or remote-tracking ref exist but share no common
31	// ancestor.
32	func IsMetadataDisconnected(ctx context.Context, repo *git.Repository, remoteRefName plumbing.ReferenceName) (bool, error) {
33		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
34		localRef, err := repo.Reference(refName, true)
35		if errors.Is(err, plumbing.ErrReferenceNotFound) {
36			return false, nil
37		}
38		if err != nil {
39			return false, fmt.Errorf("failed to check local metadata branch: %w", err)
40		}
41	
42		remoteRef, err := repo.Reference(remoteRefName, true)
43		if errors.Is(err, plumbing.ErrReferenceNotFound) {
44			return false, nil
45		}
46		if err != nil {
47			return false, fmt.Errorf("failed to check remote metadata branch: %w", err)
48		}
49	
50		if localRef.Hash() == remoteRef.Hash() {
51			return false, nil
52		}
53	
54		repoPath, err := getRepoPath(repo)
55		if err != nil {
56			return false, err
57		}
58	
59		return isDisconnected(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
60	}
61	
62	// WarnIfMetadataDisconnected checks (once per process) whether the metadata
63	// branch is disconnected and prints a warning to stderr if so.
64	// It does NOT fix the problem — users are directed to 'entire doctor'.
65	//
66	// Uses sync.Once, so a transient failure on the first call permanently suppresses
67	// the warning. This is acceptable because the check is advisory only and
68	// 'entire doctor' is the authoritative repair path.
69	func WarnIfMetadataDisconnected() {
70		disconnectedOnce.Do(func() {
71			ctx := context.Background()
72			repo, err := OpenRepository(ctx)
73			if err != nil {
74				logging.Debug(ctx, "metadata disconnection check: could not open repository",
75					slog.String("error", err.Error()))
76				return
77			}
78			defer repo.Close()
79			disconnected, err := IsMetadataDisconnected(ctx, repo, plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName))
80			if err != nil {
81				logging.Debug(ctx, "metadata disconnection check failed",
82					slog.String("error", err.Error()))
83				return
84			}
85			if !disconnected {
86				return
87			}
88			fmt.Fprintln(os.Stderr, "[entire] Warning: Local and remote session metadata branches are disconnected.")
89			fmt.Fprintln(os.Stderr, "[entire] Some checkpoints from remote may not be visible. Run 'entire doctor' to fix.")
90		})
91	}
92	
93	// ReconcileDisconnectedMetadataBranch detects and repairs disconnected local/remote
94	// entire/checkpoints/v1 branches. Disconnected means no common ancestor, which
95	// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
96	// and handled by the push path's tree merge.
97	//
98	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
99	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
100	// apply cleanly.
101	//
102	// Progress messages are written to w (typically os.Stderr for hooks or
103	// cmd.ErrOrStderr() for commands).
104	// The remote ref can be either a remote-tracking ref or a temporary fetched ref.
105	func ReconcileDisconnectedMetadataBranch(
106		ctx context.Context,
107		repo *git.Repository,
108		remoteRefName plumbing.ReferenceName,
109		w io.Writer,
110	) error {
111		refs := checkpoint.ResolveCommittedRefs(ctx)
112		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
113	
114		// Check local branch
115		localRef, err := repo.Reference(refName, true)
116		if errors.Is(err, plumbing.ErrReferenceNotFound) {
117			return nil // No local branch — nothing to reconcile
118		}
119		if err != nil {
120			return fmt.Errorf("failed to check local metadata branch: %w", err)
121		}
122	
123		// Check remote-tracking branch
124		remoteRef, err := repo.Reference(remoteRefName, true)
125		if errors.Is(err, plumbing.ErrReferenceNotFound) {
126			return nil // No remote branch — nothing to reconcile
127		}
128		if err != nil {
129			return fmt.Errorf("failed to check remote metadata branch: %w", err)
