// checkpointHasSessionMetadata reports whether the checkpoint has metadata for
// sessionID. Reads target Primary directly even when refs.Read is the v1.1
// mirror because this is a write-side defense-in-depth check (does WriteCommitted
// have a slot to overwrite?), not a read-side query. A stale mirror would let
// the guard miss a slot that WriteCommitted's findSessionIndex would then reuse,
// silently overwriting the original session metadata.
func checkpointHasSessionMetadata(ctx context.Context, repo *git.Repository, refs cpkg.CommittedRefs, checkpointID id.CheckpointID, sessionID string) (bool, error) {
	primaryRefs := refs
	primaryRefs.Read = refs.Primary
	store := cpkg.NewGitStore(repo, primaryRefs)
	summary, err := store.ReadCommitted(ctx, checkpointID)
	if err != nil {
		return false, fmt.Errorf("read checkpoint summary: %w", err)
	}
	if summary == nil {
		return false, nil
	}
	for i := range summary.Sessions {
		metadata, err := store.ReadSessionMetadata(ctx, checkpointID, i)
		if err != nil {
			return false, fmt.Errorf("read session %d metadata: %w", i, err)
		}
		if metadata != nil && metadata.SessionID == sessionID {
			return true, nil
		}
	}
	return false, nil
}

