	if summary == nil {
		return false, nil
	}
	for i := range summary.Sessions {
		metadata, err := store.ReadSessionMetadata(ctx, checkpointID, i)
		if err != nil {
			return false, fmt.Errorf("read session %d metadata: %w", i, err)
		}
		if metadata != nil && metadata.SessionID == sessionID {
			return true, nil
		}
	}
	return false, nil
}

